// Definition for a binary tree node.
// class TreeNode {
//     int val;
//     TreeNode left;
//     TreeNode right;
//     TreeNode(int x) { val = x; }
// }
public int diameterOfBinaryTree(TreeNode root) {
    if (root == null) {
        return 0;
    }
    int bendHere = height(root.left) + height(root.right);
    int best = bendHere;
    best = Math.max(best, diameterOfBinaryTree(root.left));
    best = Math.max(best, diameterOfBinaryTree(root.right));
    return best;
}

// Longest downward chain from node, counted in edges.
private int height(TreeNode node) {
    if (node == null) {
        return 0;
    }
    return 1 + Math.max(height(node.left), height(node.right));
}

