    def height(node: 'TreeNode') -> int:
        if node is None:
            return 0
        return 1 + max(height(node.left), height(node.right))

    def best_bend(node: 'TreeNode') -> int:
        if node is None:
            return 0
        bend_here = height(node.left) + height(node.right)
        return max(bend_here, best_bend(node.left), best_bend(node.right))

    return best_bend(root)

